settings.custom_liquid:
{% comment %}
  Happy Hair responsive slideshow
  Paste this entire file into a Shopify "Custom liquid" section.
{% endcomment %}

<section
  id="happy-hair-slider-{{ section.id }}"
  class="happy-hair-slider"
  aria-roledescription="carousel"
  aria-label="Featured products"
  tabindex="0"
>
  <div class="happy-hair-slider__track">
    <article class="happy-hair-slide happy-hair-slide--left is-active" aria-hidden="false">
      <picture>
        <source media="(max-width: 749px)" srcset="https://cdn.shopify.com/s/files/1/0823/0748/1873/files/mobile_version_bannner_every_adventure_without_text.webp?v=1781884893">
        <img src="https://cdn.shopify.com/s/files/1/0823/0748/1873/files/home_banner_2_without_text.webp?v=1781884893" alt="Happy hair care for growing children" width="1920" height="760" loading="eager" fetchpriority="high">
      </picture>
      <div class="happy-hair-slide__content">
        <h2>Made for Happy Hair Days</h2>
        <p>For the growing years when every little moment matters</p>
        <a href="/collections/all">Find the right Products</a>
      </div>
    </article>

    <article class="happy-hair-slide happy-hair-slide--right" aria-hidden="true">
      <picture>
        <source media="(max-width: 749px)" srcset="https://cdn.shopify.com/s/files/1/0823/0748/1873/files/mobile_version_bannner_visible_result_without_text.webp?v=1781884893">
        <img src="https://cdn.shopify.com/s/files/1/0823/0748/1873/files/home_banner_3_withou_text.webp?v=1781884893" alt="Gentle hair care with visible results" width="1920" height="760" loading="lazy">
      </picture>
      <div class="happy-hair-slide__content">
        <h2>Made for Happy Hair Days</h2>
        <p>For the growing years when every little moment matters</p>
        <a href="/collections/all">Find the right Products</a>
      </div>
    </article>

    <article class="happy-hair-slide happy-hair-slide--right" aria-hidden="true">
      <picture>
        <source media="(max-width: 749px)" srcset="https://cdn.shopify.com/s/files/1/0823/0748/1873/files/mobile_version_bannner_power_packed_without_text.webp?v=1781884892">
        <img src="https://cdn.shopify.com/s/files/1/0823/0748/1873/files/home_banner_4_without_text.webp?v=1781884893" alt="Power-packed hair care for children" width="1920" height="760" loading="lazy">
      </picture>
      <div class="happy-hair-slide__content">
        <h2>Made for Happy Hair Days</h2>
        <p>For the growing years when every little moment matters</p>
        <a href="/collections/all">Find the right Products</a>
      </div>
    </article>
  </div>

  <button class="happy-hair-slider__arrow happy-hair-slider__arrow--prev" type="button" aria-label="Previous slide">&#10094;</button>
  <button class="happy-hair-slider__arrow happy-hair-slider__arrow--next" type="button" aria-label="Next slide">&#10095;</button>

  <div class="happy-hair-slider__dots" aria-label="Choose a slide">
    <button class="is-active" type="button" aria-label="Show slide 1" aria-current="true"></button>
    <button type="button" aria-label="Show slide 2" aria-current="false"></button>
    <button type="button" aria-label="Show slide 3" aria-current="false"></button>
  </div>
  <p class="happy-hair-slider__status visually-hidden" aria-live="polite">Slide 1 of 3</p>
</section>

<style>
  #happy-hair-slider-{{ section.id }} {
    --banner-text: #3f2740;
    --banner-button: #563258;
    --banner-button-text: #fff;
    position: relative;
    width: 100%;
    overflow: hidden;
    background: #f7ede6;
    isolation: isolate;
    line-height: normal;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__track {
    display: grid;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide {
    grid-area: 1 / 1;
    position: relative;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition: opacity .55s ease, visibility .55s ease;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide.is-active {
    z-index: 1;
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
  }

  #happy-hair-slider-{{ section.id }} picture,
  #happy-hair-slider-{{ section.id }} img {
    display: block;
    width: 100%;
  }

  #happy-hair-slider-{{ section.id }} img {
    height: auto;
    object-fit: cover;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide__content {
    position: absolute;
    z-index: 2;
    top: 50%;
    width: min(43%, 650px);
    color: var(--banner-text);
    transform: translateY(-50%);
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide--left .happy-hair-slide__content {
    left: clamp(65px, 8vw, 150px);
    right: auto;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide--right .happy-hair-slide__content {
    right: clamp(65px, 8vw, 150px);
    left: auto;
  }

  /* Force the correct safe area for each desktop image. */
  #happy-hair-slider-{{ section.id }} .happy-hair-slider__track > .happy-hair-slide:nth-child(1) .happy-hair-slide__content {
    right: auto !important;
    left: clamp(15px, 2.5vw, 45px) !important;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__track > .happy-hair-slide:nth-child(2) .happy-hair-slide__content,
  #happy-hair-slider-{{ section.id }} .happy-hair-slider__track > .happy-hair-slide:nth-child(3) .happy-hair-slide__content {
    right: clamp(65px, 8vw, 150px) !important;
    left: auto !important;
  }

  #happy-hair-slider-{{ section.id }} h2 {
    margin: 0 0 12px;
    color: inherit;
    font-size: clamp(31px, 3.15vw, 50px);
    font-weight: 700;
    line-height: 1.03;
    letter-spacing: -.03em;
    white-space: nowrap;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide__content p {
    margin: 0 0 24px;
    color: inherit;
    font-size: clamp(16px, 1.5vw, 23px);
    line-height: 1.45;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide__content a {
    display: inline-flex;
    min-height: 48px;
    align-items: center;
    justify-content: center;
    padding: 12px 25px;
    border: 2px solid var(--banner-button);
    border-radius: 999px;
    background: var(--banner-button);
    color: var(--banner-button-text);
    font-size: 16px;
    font-weight: 700;
    line-height: 1.2;
    text-decoration: none;
    transition: transform .2s ease, background .2s ease, color .2s ease;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slide__content a:hover {
    background: transparent;
    color: var(--banner-button);
    transform: translateY(-2px);
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow {
    appearance: none !important;
    -webkit-appearance: none !important;
    position: absolute;
    z-index: 3;
    top: 50%;
    width: 44px !important;
    min-width: 44px !important;
    max-width: 44px !important;
    height: 44px !important;
    min-height: 44px !important;
    max-height: 44px !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 1px solid rgb(63 39 64 / 14%) !important;
    border-radius: 50%;
    background: rgb(255 255 255 / 88%) !important;
    color: #3f2740 !important;
    font-family: Arial, sans-serif !important;
    font-size: 22px !important;
    font-weight: 400 !important;
    line-height: 42px !important;
    text-align: center !important;
    text-decoration: none !important;
    cursor: pointer;
    box-shadow: 0 3px 16px rgb(0 0 0 / 12%);
    transform: translateY(-50%);
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow::before,
  #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow::after,
  #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots button::before,
  #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots button::after {
    display: none !important;
    content: none !important;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow--prev { left: 18px; }
  #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow--next { right: 18px; }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots {
    position: absolute;
    z-index: 3;
    bottom: 18px;
    left: 50%;
    display: flex;
    gap: 9px;
    transform: translateX(-50%);
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots button {
    appearance: none !important;
    -webkit-appearance: none !important;
    display: block !important;
    width: 10px !important;
    min-width: 10px !important;
    max-width: 10px !important;
    height: 10px !important;
    min-height: 10px !important;
    max-height: 10px !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 1px solid rgb(63 39 64 / 65%) !important;
    border-radius: 50%;
    background: rgb(255 255 255 / 82%) !important;
    box-shadow: none !important;
    cursor: pointer;
    transition: width .2s ease, border-radius .2s ease, background .2s ease;
  }

  #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots button.is-active {
    width: 27px !important;
    min-width: 27px !important;
    max-width: 27px !important;
    border-radius: 999px;
    background: var(--banner-button) !important;
  }

  #happy-hair-slider-{{ section.id }} .visually-hidden {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
  }

  @media (max-width: 749px) {
    #happy-hair-slider-{{ section.id }} .happy-hair-slide__content {
      top: 3.5%;
      width: 86%;
      text-align: center;
      transform: none;
    }

    #happy-hair-slider-{{ section.id }} .happy-hair-slide--left .happy-hair-slide__content,
    #happy-hair-slider-{{ section.id }} .happy-hair-slide--right .happy-hair-slide__content {
      right: auto;
      left: 7%;
    }

    #happy-hair-slider-{{ section.id }} .happy-hair-slider__track > .happy-hair-slide:nth-child(1) .happy-hair-slide__content,
    #happy-hair-slider-{{ section.id }} .happy-hair-slider__track > .happy-hair-slide:nth-child(2) .happy-hair-slide__content,
    #happy-hair-slider-{{ section.id }} .happy-hair-slider__track > .happy-hair-slide:nth-child(3) .happy-hair-slide__content {
      right: auto !important;
      left: 7% !important;
    }

    #happy-hair-slider-{{ section.id }} h2 {
      margin-bottom: 6px;
      font-size: clamp(27px, 7.5vw, 36px);
      line-height: 1.04;
      white-space: normal;
    }

    #happy-hair-slider-{{ section.id }} .happy-hair-slide__content p {
      max-width: 360px;
      margin: 0 auto 11px;
      font-size: clamp(13px, 3.5vw, 16px);
      line-height: 1.32;
    }

    #happy-hair-slider-{{ section.id }} .happy-hair-slide__content a {
      min-height: 40px;
      padding: 8px 18px;
      font-size: 13px;
    }

    #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow {
      width: 36px !important;
      min-width: 36px !important;
      max-width: 36px !important;
      height: 36px !important;
      min-height: 36px !important;
      max-height: 36px !important;
      font-size: 18px !important;
      line-height: 34px !important;
    }

    #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow--prev { left: 8px; }
    #happy-hair-slider-{{ section.id }} .happy-hair-slider__arrow--next { right: 8px; }
    #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots { bottom: 11px; }
  }

  @media (prefers-reduced-motion: reduce) {
    #happy-hair-slider-{{ section.id }} .happy-hair-slide,
    #happy-hair-slider-{{ section.id }} .happy-hair-slide__content a,
    #happy-hair-slider-{{ section.id }} .happy-hair-slider__dots button {
      transition: none;
    }
  }
</style>

<script>
  (() => {
    const root = document.getElementById('happy-hair-slider-{{ section.id }}');
    if (!root || root.dataset.ready === 'true') return;
    root.dataset.ready = 'true';

    const slides = [...root.querySelectorAll('.happy-hair-slide')];
    const dots = [...root.querySelectorAll('.happy-hair-slider__dots button')];
    const status = root.querySelector('.happy-hair-slider__status');
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let current = 0;
    let timer;
    let touchStartX = 0;

    const show = (index, announce = true) => {
      current = (index + slides.length) % slides.length;
      slides.forEach((slide, i) => {
        const active = i === current;
        slide.classList.toggle('is-active', active);
        slide.setAttribute('aria-hidden', String(!active));
      });
      dots.forEach((dot, i) => {
        const active = i === current;
        dot.classList.toggle('is-active', active);
        dot.setAttribute('aria-current', String(active));
      });
      if (announce) status.textContent = `Slide ${current + 1} of ${slides.length}`;
    };

    const stop = () => window.clearInterval(timer);
    const start = () => {
      stop();
      if (!reduceMotion) timer = window.setInterval(() => show(current + 1, false), 5500);
    };

    root.querySelector('.happy-hair-slider__arrow--prev').addEventListener('click', () => { show(current - 1); start(); });
    root.querySelector('.happy-hair-slider__arrow--next').addEventListener('click', () => { show(current + 1); start(); });
    dots.forEach((dot, i) => dot.addEventListener('click', () => { show(i); start(); }));

    root.addEventListener('mouseenter', stop);
    root.addEventListener('mouseleave', start);
    root.addEventListener('focusin', stop);
    root.addEventListener('focusout', start);
    root.addEventListener('keydown', (event) => {
      if (event.key === 'ArrowLeft') { show(current - 1); start(); }
      if (event.key === 'ArrowRight') { show(current + 1); start(); }
    });

    root.addEventListener('touchstart', (event) => { touchStartX = event.changedTouches[0].clientX; }, { passive: true });
    root.addEventListener('touchend', (event) => {
      const distance = event.changedTouches[0].clientX - touchStartX;
      if (Math.abs(distance) < 45) return;
      show(distance > 0 ? current - 1 : current + 1);
      start();
    }, { passive: true });

    document.addEventListener('visibilitychange', () => document.hidden ? stop() : start());
    show(0, false);
    start();
  })();
</script>
